"""Check 10 and kb/notation.md: one symbol, one meaning across the concept notes' notation fields.

A paper note may also map its source's symbols to canonical ones in a "## Notation" table
(Source | Meaning in this source | Canonical | Note); the Canonical cell is one $symbol$ or —."""

import re

from model import Issue

COMMENT = re.compile(r"<!--.*?-->", re.S)
MAP_HEADING = re.compile(r"^##\s+Notation\s*$")
CANONICAL = re.compile(r"^\$([^$]+)\$$")
NO_CANONICAL = {"—", "-", "–"}
WRAPPER = re.compile(r"\\(?:text|mathrm|operatorname)\{([^{}]*)\}")
HEADER = (
    "<!-- Generated by tools/kb-lint/lint.py --write. Do not edit by hand. -->\n"
    "# Notation\n\n"
    "Every symbol declared in a concept note's `notation:` field. Change a symbol in its concept note, not here.\n"
    "\"Written in sources\" collects the paper notes' `## Notation` maps: how each source writes the canonical symbol.\n"
)


def symbol_key(symbol):
    """'k_{\\mathrm{int}}' and 'k_\\text{int}' both -> 'k_int'."""
    while (unwrapped := WRAPPER.sub(r"\1", symbol)) != symbol:
        symbol = unwrapped
    return re.sub(r"[\s{}]", "", symbol)


def meaning_key(meaning):
    return re.sub(r"[^\w]+", " ", meaning.lower()).strip()


def _entries(vault):
    """(note, symbol, meaning, units) for every well-formed notation entry, notes in path order."""
    for note in sorted(vault.notes, key=lambda n: n.rel):
        if note.type != "concept":
            continue
        for entry in note.meta.get("notation") or []:
            if isinstance(entry, dict) and isinstance(entry.get("symbol"), str) and isinstance(entry.get("meaning"), str):
                yield note, entry["symbol"], entry["meaning"], entry.get("units")


def _map_rows(note):
    """(rows, problems) for the first table under a paper note's '## Notation' heading.

    rows are (source symbol, canonical symbol or None); problems are warning messages."""
    text = COMMENT.sub("", "".join(note.lines))
    lines = text.splitlines()
    start = next((i for i, line in enumerate(lines) if MAP_HEADING.match(line)), None)
    if start is None:
        return [], []
    section = []
    for line in lines[start + 1:]:
        if line.startswith("## "):
            break
        section.append(line.strip())
    table = []
    for line in section:
        if line.startswith("|"):
            table.append(line)
        elif table:
            break
    if not table:
        if any(section):
            return [], ["Notation section has no table; use | Source | Meaning in this source | Canonical | Note |"]
        return [], []
    rows, problems = [], []
    for line in table[1:]:
        cells = [cell.strip() for cell in line.strip("|").split("|")]
        if all(re.fullmatch(r":?-+:?", cell) for cell in cells):
            continue
        if len(cells) != 4:
            problems.append(f"Notation row '{line}' needs 4 columns (Source | Meaning in this source | Canonical | Note)")
            continue
        source, _, canonical, _ = cells
        if canonical in NO_CANONICAL:
            rows.append((source, None))
        elif match := CANONICAL.match(canonical):
            rows.append((source, match.group(1)))
        else:
            problems.append(f"Notation row for {source}: canonical cell must be one $symbol$ or —, not '{canonical}'")
    return rows, problems


def _source_maps(vault):
    """(paper note, rows, problems) for every paper note with a Notation section, in path order."""
    for note in sorted(vault.notes, key=lambda n: n.rel):
        if note.type == "paper":
            rows, problems = _map_rows(note)
            if rows or problems:
                yield note, rows, problems


def check_notation(vault):
    issues, first = [], {}
    for note, symbol, meaning, _ in _entries(vault):
        key = symbol_key(symbol)
        if key not in first:
            first[key] = (note, meaning)
            continue
        other, other_meaning = first[key]
        if meaning_key(meaning) != meaning_key(other_meaning):
            issues.append(Issue(
                "warning", 10, note.rel,
                f"'{symbol}' means '{meaning}' here but '{other_meaning}' in [[{other.name}]]",
            ))
    for note, rows, problems in _source_maps(vault):
        issues += [Issue("warning", 10, note.rel, message) for message in problems]
        for source, canonical in rows:
            if canonical is not None and symbol_key(canonical) not in first:
                issues.append(Issue(
                    "warning", 10, note.rel,
                    f"'{source}' maps to canonical '${canonical}$', which no concept declares",
                ))
    return issues


def render_notation(vault):
    rows = {}
    for note, symbol, meaning, units in _entries(vault):
        row = rows.setdefault((symbol_key(symbol), meaning_key(meaning)), [symbol, meaning, units, []])
        if note.name not in row[3]:
            row[3].append(note.name)
    forms = {}  # canonical symbol key -> {source symbol key: [source symbol, [paper names]]}
    for note, map_rows, _ in _source_maps(vault):
        for source, canonical in map_rows:
            if canonical is None:
                continue
            form = forms.setdefault(symbol_key(canonical), {}).setdefault(symbol_key(source), [source, []])
            if note.name not in form[1]:
                form[1].append(note.name)
    lines = [
        "| Symbol | Meaning | Units | Defined in | Written in sources |",
        "|---|---|---|---|---|",
    ]
    for key in sorted(rows):
        symbol, meaning, units, names = rows[key]
        written = ", ".join(
            f"{source} ({', '.join(f'[[{n}]]' for n in papers)})"
            for source, papers in forms.get(key[0], {}).values()
        )
        lines.append(
            f"| ${symbol}$ | {meaning} | {units or '—'} | {', '.join(f'[[{n}]]' for n in names)} | {written or '—'} |"
        )
    return HEADER + "\n" + "\n".join(lines) + "\n"
